import { useGet, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import React, { useEffect, useMemo } from 'react'
import { useParams } from 'react-router'
import BackButton from '../../../components/BackButton'
import { actions } from '../apiConfig'
import SMELeadDetail from './SMELeadDetail'
import Form from './Form'
import { Spin } from 'antd'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const SMELeadsDetailComponent = ({ form }) => {
  const [smeDetail, smeDetailRequest] = useGet(actions.getSMEDetail)
  const [config, configRequest] = useGet(actions.getSMELeadConfig)
  const [{ SME_DETAILS_LOADER, SME_LEAD_CONFIG_LOADER, SME_LEAD_UPDATE_LOADER }] = useLoaderContextValue()
  const params = useParams()

  const statusEvents = useMemo(() => {
    return config?.lead_events?.filter(({ source }) => source === smeDetail?.lead_status)
  }, [smeDetail, config])

  useEffect(() => {
    smeDetailRequest({ id: params.leadId })
  }, [params, smeDetailRequest])

  useEffect(() => {
    configRequest()
  }, [configRequest])

  return (
    <>
      <BackButton goBackLocation='/employee-benefits/sme-prepackage-leads/' />
      <Spin spinning={!!(SME_DETAILS_LOADER || SME_LEAD_CONFIG_LOADER || SME_LEAD_UPDATE_LOADER)}>
        <SMELeadDetail smeDetail={smeDetail} statusOptions={config?.lead_status} prePackages={config?.pre_package_types} />
        <PermissionCheckerV2 requiredPermission='ops.eb_update_lead'>
          <Form
            detailData={smeDetail}
            statusOptions={config?.lead_status}
            statusEvents={statusEvents}
          />
        </PermissionCheckerV2>
      </Spin>
    </>
  )
}

export default SMELeadsDetailComponent
