import { useErrorContextValue, useGet, usePost, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, Form, Input, message, Row, Select } from 'antd'
import React, { useCallback, useEffect } from 'react'
import { EbSectionWrapper } from '../../../../CommonComponents'
import { actions } from '../../apiConfig'

const SMEForm = ({ form, id, detailData, statusEvents, statusOptions }) => {
  const [, statusRequest] = usePost(actions.postSMELeadUpdate)
  const { getFieldDecorator, getFieldValue, validateFields, resetFields } = form
  const [{ SME_LEAD_UPDATE_ERROR, smeLeadUpdateStatus, smeLeadUpdateErrorData }] = useErrorContextValue()
  const [, smeDetailRequest] = useGet(actions.getSMEDetail)
  const { resetError } = useResetError()
  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    validateFields((err, values) => {
      if (!err) {
        statusRequest({
          ...values,
          reference_id: detailData?.reference_id
        })
      }
    })
  }, [detailData, validateFields, statusRequest])

  useEffect(() => {
    if (smeLeadUpdateStatus === 'success') {
      resetFields()
      smeDetailRequest({ id: detailData?.id })
      message.success('Status updated successfully')
      resetError([
        'smeLeadUpdateStatus'
      ])
    }
  }, [smeLeadUpdateStatus, resetFields, smeDetailRequest, detailData, resetError])

  useEffect(() => {
    return () => {
      resetError([
        'SME_LEAD_UPDATE_ERROR',
        'smeLeadUpdateStatus'
      ])
    }
  }, [resetError])

  return (
    <EbSectionWrapper>
      <h2>Update Lead</h2>
      {
        SME_LEAD_UPDATE_ERROR &&
          <div className='mb-5'>
            <Alert type='error' message={smeLeadUpdateErrorData?.message || smeLeadUpdateStatus} banner />
          </div>
      }
      <Form
        onSubmit={handleSubmit}
      >
        <Row gutter={32}>
          <Col span={8}>
            <Form.Item
              required
              label='Lead Status'
            >
              {
                getFieldDecorator('event_code', {
                  rules: [
                    {
                      required: true,
                      message: 'This field is required'
                    }
                  ]
                })(
                  <Select
                    disabled={detailData?.lead_status === 'WINNING' && detailData?.is_company_created}
                  >
                    {statusEvents?.map((status, index) => {
                      return <Select.Option key={index} value={status.code}>{status.name}</Select.Option>
                    })}
                  </Select>
                )
              }
            </Form.Item>
          </Col>
          {
            getFieldValue('event_code') === 'lose' && (
              <Col span={8}>
                <Form.Item
                  required
                  label='Lose case reason'
                >
                  {
                    getFieldDecorator('internal_remarks', {
                      rules: [
                        {
                          required: true,
                          message: 'This field is required'
                        }
                      ]
                    })(
                      <Input.TextArea />
                    )
                  }
                </Form.Item>
              </Col>
            )
          }
        </Row>
        <Row gutter={32}>
          <Col span={8}>
            <Form.Item>
              <Button
                type='primary'
                htmlType='submit'
                block
              >Update Detail
              </Button>
            </Form.Item>
          </Col>
        </Row>
      </Form>
    </EbSectionWrapper>
  )
}

export default Form.create({ name: 'new-case-form' })(SMEForm)
