import { Col, Row, Tag, Typography } from 'antd'
import React, { useMemo } from 'react'
import { formatIntlCurrency } from '../../../../../../../helpers/utility'
import { EbSectionWrapper, RowWithMargin } from '../../../../CommonComponents'
import { TagWithMargin } from './index.style'

const { Text } = Typography

function PrepackagesLabel (prePackages = []) {
  prePackages.forEach(({ code, name }) => {
    this[code] = name
  })
}

function LeadStatusLabel (statusOptions = []) {
  statusOptions.forEach(({ code, name }) => {
    this[code] = name
  })
}

const SMELeadDetail = ({ smeDetail, statusOptions, prePackages }) => {
  const prepackageLabel = useMemo(() => {
    return new PrepackagesLabel(prePackages)
  }, [prePackages])

  const statusLabels = useMemo(() => {
    return new LeadStatusLabel(statusOptions)
  }, [statusOptions])

  const firstRowRecords = useMemo(() => ([
    { heading: 'Company Name', data: smeDetail?.company_name },
    { heading: 'Name', data: smeDetail?.name },
    { heading: 'Created at', data: smeDetail?.created_at },
    { heading: 'Email', data: smeDetail?.work_email },
    { heading: 'SME Prepackage', data: <Tag color='magenta'>{prepackageLabel[smeDetail?.sme_prepackage]}</Tag> },
    { heading: 'Email Verified at ', data: smeDetail?.email_verified_at },
    { heading: 'Internal Remarks', data: smeDetail?.internal_remarks },
    { heading: 'User Remarks', data: smeDetail?.remarks }
  ]), [smeDetail, prepackageLabel])

  const secondRowRecords = useMemo(() => ([
    { heading: 'Id', data: smeDetail?.id },
    { heading: 'Phone', data: smeDetail?.phone },
    { heading: 'Total Payable Price', data: <Tag color='green'>{formatIntlCurrency(smeDetail?.total_payable_price)}</Tag> },
    { heading: 'Verification date', data: smeDetail?.verification_date },
    { heading: 'Lead Status Updated At', data: smeDetail?.lead_status_updated_at },
    { heading: 'Lead Previous Status', data: statusLabels[smeDetail?.previous_status] },
    { heading: 'Lead Status', data: statusLabels[smeDetail?.lead_status] },
    {
      heading: 'Participants Count',
      data: (
        <div>
          <TagWithMargin color='blue'>Total - {smeDetail?.total_participants}</TagWithMargin>
          <TagWithMargin color='volcano'>Male - {smeDetail?.participant_count?.MALE}</TagWithMargin>
          <TagWithMargin color='pink'>Female - {smeDetail?.participant_count?.FEMALE}</TagWithMargin>
          <TagWithMargin color='purple'>Children - {smeDetail?.participant_count?.CHILD}</TagWithMargin>
        </div>
      )
    }
  ]), [smeDetail, statusLabels])

  return (
    <EbSectionWrapper>
      <h2>SME Lead Detail</h2>
      <Row gutter={32}>
        <Col span={12}>
          {
            firstRowRecords.map(({ heading, data }) => (
              <RowWithMargin key={heading}>
                <Col span={12}><Text strong>{heading}</Text></Col>
                <Col span={12}>{data}</Col>
              </RowWithMargin>
            ))
          }
        </Col>
        <Col span={12}>
          {
            secondRowRecords.map(({ heading, data }) => (
              <RowWithMargin key={heading}>
                <Col span={12}><Text strong>{heading}</Text></Col>
                <Col span={12}>{data}</Col>
              </RowWithMargin>
            ))
          }
        </Col>
      </Row>
    </EbSectionWrapper>
  )
}

export default SMELeadDetail
